-- PT101-S3-Q15. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT101-S3-Q15$batch11$ AND q.stimulus=$batch11$Dr. Z: Many of the characterizations of my work offered by Dr. Q are imprecise, and such characterizations do not provide an adequate basis for sound criticism of my work.$batch11$ AND q.prompt=$batch11$Which one of the following can be properly inferred from Dr. Z's statement?$batch11$ AND q.correct_choice=$batch11$E$batch11$) THEN RAISE EXCEPTION 'Question changed: PT101-S3-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT101-S3-Q15$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S3-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT101-S3-Q15$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Many of Dr. Q's characterizations of Dr. Z's work are imprecise. Such imprecise characterizations do not give an adequate basis for sound criticism.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$"Such characterizations" points back to the imprecise ones. So: many characterizations are imprecise, and every imprecise one fails as a basis for criticism. "Many" guarantees at least one. So at least one characterization fails as a basis for criticism. We learn nothing about the precise ones.$batch11$), (2, $batch11$Goal$batch11$, $batch11$At least one of Dr. Q's characterizations fails to give an adequate basis for criticism.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT101-S3-Q15$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$We know nothing about the precise characterizations. Every one of Dr. Q's characterizations could be imprecise, and then none would work.$batch11$), ($batch11$B$batch11$, $batch11$This assumes precision is enough for a sound basis. Dr. Z only says imprecision is enough to fail.$batch11$), ($batch11$C$batch11$, $batch11$Dr. Z says imprecise → inadequate. This says inadequate → imprecise. A characterization could be precise and still inadequate for some other reason.$batch11$), ($batch11$D$batch11$, $batch11$Same mistake as (B), now stated as a general rule about anyone's work.$batch11$), ($batch11$E$batch11$, $batch11$Many characterizations are imprecise, and imprecise ones are inadequate. So at least one is inadequate.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT101-S3-Q15$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
